"""Email provider protocol and deterministic credential-free fake."""

from __future__ import annotations

from collections import deque
from datetime import datetime
from enum import StrEnum
from typing import Protocol

from sentinel_api.email.models import (
    DispatchDisposition,
    EmailDispatchRequest,
    ProviderDispatchResult,
    ProviderReceipt,
    ProviderReconciliationResult,
    ReconciliationDisposition,
)


class EmailProvider(Protocol):
    async def dispatch(self, request: EmailDispatchRequest) -> ProviderDispatchResult:
        """Attempt one payload-bound provider dispatch."""

    async def reconcile(
        self,
        request: EmailDispatchRequest,
        provider_reference: str | None,
    ) -> ProviderReconciliationResult:
        """Resolve an ambiguous dispatch before any retry."""


class FakeProviderBehavior(StrEnum):
    CONFIRM = "confirm"
    FAIL_BEFORE_EFFECT = "fail_before_effect"
    TIMEOUT_BEFORE_EFFECT = "timeout_before_effect"
    AMBIGUOUS_CONFIRMED = "ambiguous_confirmed"
    AMBIGUOUS_NOT_SENT = "ambiguous_not_sent"
    AMBIGUOUS_UNRESOLVED = "ambiguous_unresolved"


class DeterministicFakeEmailProvider:
    """Scriptable provider that never performs I/O and deduplicates by request key."""

    def __init__(
        self,
        behaviors: tuple[FakeProviderBehavior, ...] = (FakeProviderBehavior.CONFIRM,),
    ) -> None:
        if not behaviors:
            raise ValueError("fake provider requires at least one behavior")
        self._behaviors = deque(behaviors)
        self._receipts: dict[str, ProviderReceipt] = {}
        self._unknown_behavior: dict[str, FakeProviderBehavior] = {}
        self.dispatch_calls: list[EmailDispatchRequest] = []
        self.reconciliation_calls: list[tuple[EmailDispatchRequest, str | None]] = []

    async def dispatch(self, request: EmailDispatchRequest) -> ProviderDispatchResult:
        self.dispatch_calls.append(request)
        existing = self._receipts.get(request.idempotency_key)
        if existing is not None:
            return ProviderDispatchResult(
                disposition=DispatchDisposition.CONFIRMED,
                receipt=existing,
                detail="Fake provider returned the existing idempotent receipt",
            )

        behavior = self._behaviors[0]
        if len(self._behaviors) > 1:
            behavior = self._behaviors.popleft()
        if behavior is FakeProviderBehavior.CONFIRM:
            receipt = self._receipt(request)
            self._receipts[request.idempotency_key] = receipt
            return ProviderDispatchResult(
                disposition=DispatchDisposition.CONFIRMED,
                receipt=receipt,
                detail="Fake provider accepted the message",
            )
        if behavior in {
            FakeProviderBehavior.FAIL_BEFORE_EFFECT,
            FakeProviderBehavior.TIMEOUT_BEFORE_EFFECT,
        }:
            return ProviderDispatchResult(
                disposition=DispatchDisposition.FAILED_BEFORE_EFFECT,
                detail="Fake provider failed before accepting the message",
            )

        self._unknown_behavior[request.idempotency_key] = behavior
        provider_reference = None
        if behavior is FakeProviderBehavior.AMBIGUOUS_CONFIRMED:
            receipt = self._receipt(request)
            self._receipts[request.idempotency_key] = receipt
            provider_reference = receipt.message_id
        return ProviderDispatchResult(
            disposition=DispatchDisposition.OUTCOME_UNKNOWN,
            provider_reference=provider_reference,
            detail="Fake provider outcome is ambiguous",
        )

    async def reconcile(
        self,
        request: EmailDispatchRequest,
        provider_reference: str | None,
    ) -> ProviderReconciliationResult:
        self.reconciliation_calls.append((request, provider_reference))
        receipt = self._receipts.get(request.idempotency_key)
        if receipt is not None:
            return ProviderReconciliationResult(
                disposition=ReconciliationDisposition.CONFIRMED,
                receipt=receipt,
                detail="Fake provider found the accepted message",
            )
        behavior = self._unknown_behavior.get(request.idempotency_key)
        if behavior is FakeProviderBehavior.AMBIGUOUS_NOT_SENT:
            return ProviderReconciliationResult(
                disposition=ReconciliationDisposition.SAFE_TO_RETRY,
                detail="Fake provider confirmed that no message was accepted",
            )
        return ProviderReconciliationResult(
            disposition=ReconciliationDisposition.NEEDS_OPERATOR,
            detail="Fake provider could not resolve the ambiguous outcome",
        )

    @staticmethod
    def _receipt(request: EmailDispatchRequest) -> ProviderReceipt:
        reference = f"fake-{request.idempotency_key[:24]}"
        return ProviderReceipt(
            provider="fake",
            message_id=reference,
            accepted_at=request.authorized_at,
            status="accepted",
        )

"""Resend-compatible provider adapter with an injected authenticated transport."""

from __future__ import annotations

from collections.abc import Callable, Mapping
from datetime import datetime, timedelta
from enum import StrEnum
from typing import Protocol

from pydantic import Field

from sentinel_api.domain import ContractModel, utc_now
from sentinel_api.email.models import (
    DispatchDisposition,
    EmailDispatchRequest,
    ProviderDispatchResult,
    ProviderReceipt,
    ProviderReconciliationResult,
    ReconciliationDisposition,
)


class TransportEffect(StrEnum):
    NOT_APPLIED = "not_applied"
    UNKNOWN = "unknown"


class ResendTransportError(RuntimeError):
    """Sanitized transport failure classified by whether an effect was possible."""

    def __init__(self, message: str, *, effect: TransportEffect) -> None:
        super().__init__(message)
        self.effect = effect


class ResendTransportResponse(ContractModel):
    status_code: int = Field(ge=100, le=599)
    body: dict[str, object] = Field(default_factory=dict)


class ResendTransport(Protocol):
    async def request(
        self,
        *,
        method: str,
        path: str,
        headers: Mapping[str, str],
        json_body: Mapping[str, object] | None,
    ) -> ResendTransportResponse:
        """Perform authenticated I/O outside this adapter without exposing credentials."""


class ResendEmailProvider:
    """Translate neutral requests to Resend's HTTP shape without owning secrets."""

    def __init__(
        self,
        transport: ResendTransport,
        *,
        clock: Callable[[], datetime] = utc_now,
        idempotency_window: timedelta = timedelta(hours=24),
    ) -> None:
        if idempotency_window <= timedelta(0):
            raise ValueError("idempotency window must be positive")
        self._transport = transport
        self._clock = clock
        self._idempotency_window = idempotency_window

    async def dispatch(self, request: EmailDispatchRequest) -> ProviderDispatchResult:
        try:
            response = await self._transport.request(
                method="POST",
                path="/emails",
                headers={"Idempotency-Key": request.idempotency_key},
                json_body={
                    "from": request.message.sender,
                    "to": [request.message.recipient],
                    "subject": request.message.subject,
                    "text": request.message.text_body,
                },
            )
        except ResendTransportError as error:
            disposition = (
                DispatchDisposition.FAILED_BEFORE_EFFECT
                if error.effect is TransportEffect.NOT_APPLIED
                else DispatchDisposition.OUTCOME_UNKNOWN
            )
            return ProviderDispatchResult(
                disposition=disposition,
                detail="Resend transport failed before effect"
                if disposition is DispatchDisposition.FAILED_BEFORE_EFFECT
                else "Resend transport outcome is unknown",
            )

        if 200 <= response.status_code < 300:
            message_id = response.body.get("id")
            if not isinstance(message_id, str):
                return ProviderDispatchResult(
                    disposition=DispatchDisposition.OUTCOME_UNKNOWN,
                    detail="Resend accepted the request without a usable message reference",
                )
            receipt = ProviderReceipt(
                provider="resend",
                message_id=message_id,
                accepted_at=self._clock(),
                status="accepted",
            )
            return ProviderDispatchResult(
                disposition=DispatchDisposition.CONFIRMED,
                receipt=receipt,
                detail="Resend accepted the email",
            )
        if 400 <= response.status_code < 500:
            return ProviderDispatchResult(
                disposition=DispatchDisposition.FAILED_BEFORE_EFFECT,
                detail=f"Resend rejected the request with status {response.status_code}",
            )
        return ProviderDispatchResult(
            disposition=DispatchDisposition.OUTCOME_UNKNOWN,
            detail=f"Resend returned ambiguous status {response.status_code}",
        )

    async def reconcile(
        self,
        request: EmailDispatchRequest,
        provider_reference: str | None,
    ) -> ProviderReconciliationResult:
        if provider_reference is None:
            if self._clock() - request.authorized_at < self._idempotency_window:
                return ProviderReconciliationResult(
                    disposition=ReconciliationDisposition.SAFE_TO_RETRY,
                    detail="Resend idempotency window permits replay with the same request key",
                )
            return ProviderReconciliationResult(
                disposition=ReconciliationDisposition.NEEDS_OPERATOR,
                detail="Resend idempotency window elapsed before reconciliation",
            )

        try:
            response = await self._transport.request(
                method="GET",
                path=f"/emails/{provider_reference}",
                headers={},
                json_body=None,
            )
        except ResendTransportError:
            return ProviderReconciliationResult(
                disposition=ReconciliationDisposition.NEEDS_OPERATOR,
                provider_reference=provider_reference,
                detail="Resend receipt lookup did not produce a definitive result",
            )
        if response.status_code == 200:
            message_id = response.body.get("id")
            if message_id != provider_reference:
                return ProviderReconciliationResult(
                    disposition=ReconciliationDisposition.NEEDS_OPERATOR,
                    provider_reference=provider_reference,
                    detail="Resend receipt lookup returned a mismatched reference",
                )
            status = response.body.get("last_event", "accepted")
            if not isinstance(status, str):
                status = "accepted"
            receipt = ProviderReceipt(
                provider="resend",
                message_id=provider_reference,
                accepted_at=self._clock(),
                status=status,
            )
            return ProviderReconciliationResult(
                disposition=ReconciliationDisposition.CONFIRMED,
                receipt=receipt,
                detail="Resend confirmed the provider receipt",
            )
        return ProviderReconciliationResult(
            disposition=ReconciliationDisposition.NEEDS_OPERATOR,
            provider_reference=provider_reference,
            detail=f"Resend receipt lookup returned status {response.status_code}",
        )

